#include <bits/stdc++.h>
using namespace std;

struct arc {
  int src, tgt;
  double cap;
  arc(int s, int d, double c) : src(s), tgt(d), cap(c) {}
};

struct vtx {
  vector<int> adj;
};

struct flow_net {
  vector<vtx> V;
  vector<arc> A;

  flow_net(int nv, int na) : V(nv), A() { A.reserve(na); }

  void add_arc(int s, int t, double c) {
    A.emplace_back(s, t, c);
    V[s].adj.push_back(int(A.size()) - 1);
  }

  vector<int> bfs_path(int src, int dst, const vector<double>& f, double* cap) {
    using node_cap = pair<double,int>;
    set<node_cap, greater<node_cap>> pq;
    vector<double> dist(V.size(), 0.0);
    vector<int> prev(V.size(), -1);

    dist[src] = DBL_MAX;
    pq.emplace(dist[src], src);

    while (!pq.empty() && dist[dst] == 0) {
      auto [c, u] = *pq.begin();
      pq.erase(pq.begin());

      for (int idx : V[u].adj) {
        const arc& a = A[idx];
        double res = a.cap - f[idx];
        if (res > 0) {
          double nc = min(c, res);
          if (nc > dist[a.tgt]) {
            pq.erase({dist[a.tgt], a.tgt});
            dist[a.tgt] = nc;
            pq.emplace(dist[a.tgt], a.tgt);
            prev[a.tgt] = idx;
          }
        }
      }
    }

    *cap = dist[dst];
    vector<int> path;
    for (int i = prev[dst]; i != -1; i = prev[A[i].src])
      path.push_back(i);
    return path;
  }

  double calc_maxflow(int s, int t) {
    flow_net res(V.size(), int(A.size())*2);
    vector<double> flow(A.size()*2, 0.0);

    for (size_t i = 0; i < A.size(); ++i) {
      res.add_arc(A[i].src, A[i].tgt, A[i].cap);
      res.add_arc(A[i].tgt, A[i].src, 0.0);
    }

    double total = 0.0;
    double bottleneck;
    for (auto p = res.bfs_path(s, t, flow, &bottleneck); !p.empty() && bottleneck > 0;
         p = res.bfs_path(s, t, flow, &bottleneck)) {
      for (int e : p) {
        int rev = (e & 1) ? e - 1 : e + 1;
        flow[e] += bottleneck;
        flow[rev] -= bottleneck;
      }
      total += bottleneck;
    }

    for (int idx : res.V[s].adj)
      total += flow[idx];
    return total;
  }
};

int rows, steps;
struct Square {
  int r, c;
  bitset<61> contagious;
  bitset<61> reachable;
  int researchers, medkits;

  Square() : researchers(0), medkits(0) { reachable.set(); }

  int index(int t) const { return 2 + r + rows*c + rows*rows*t; }

  void seal_off() { reachable.reset(); }

  void expose(int t = 0) {
    if (reachable.test(t)) {
      reachable.reset(t);
      contagious.set(t);
    }
  }

  void infect_neighbors(int t);
};

Square arena[10][10];

void Square::infect_neighbors(int t) {
  if (contagious.test(t)) {
    expose(t + 1);
    if (r > 0) arena[r-1][c].expose(t + 1);
    if (r < rows - 1) arena[r+1][c].expose(t + 1);
    if (c > 0) arena[r][c-1].expose(t + 1);
    if (c < rows - 1) arena[r][c+1].expose(t + 1);
  }
}

string idx_to_str(int id) {
  if (id == 0) return "source";
  if (id == 1) return "sink";
  ostringstream oss;
  int r = (id - 2) % rows;
  int c = ((id - 2 - r) % (rows*rows)) / rows;
  int tm = (id - 2 - r - c*rows) / (rows*rows);
  oss << "(" << r << "," << c << "," << tm << ")";
  return oss.str();
}

int main() {
  ios::sync_with_stdio(false);
  cin >> rows >> steps;

  for (int i = 0; i < rows; ++i) {
    string line;
    cin >> line;
    for (int j = 0; j < rows; ++j) {
      arena[i][j].r = i;
      arena[i][j].c = j;
      if (line[j] == 'Y') arena[i][j].seal_off();
      else if (line[j] == 'Z') arena[i][j].expose();
      else arena[i][j].researchers = line[j] - '0';
    }
  }

  for (int i = 0; i < rows; ++i) {
    string line;
    cin >> line;
    for (int j = 0; j < rows; ++j) {
      if (line[j] != 'Y' && line[j] != 'Z')
        arena[i][j].medkits = line[j] - '0';
    }
  }

  for (int ts = 0; ts <= steps; ++ts)
    for (int i = 0; i < rows; ++i)
      for (int j = 0; j < rows; ++j)
        if (ts < steps) arena[i][j].infect_neighbors(ts);

  flow_net net(rows*rows*(steps+1)+2, 100*4*60);
  for (int i = 0; i < rows; ++i)
    for (int j = 0; j < rows; ++j) {
      const Square& sq = arena[i][j];
      if (sq.researchers) net.add_arc(0, sq.index(0), sq.researchers);
      if (sq.medkits) net.add_arc(sq.index(steps), 1, sq.medkits);
      for (int ts = 0; ts < steps; ++ts) {
        if (sq.medkits) net.add_arc(sq.index(ts), sq.index(steps), 1000);
        if (sq.reachable.test(ts)) {
          if (i > 0 && arena[i-1][j].reachable.test(ts))
            net.add_arc(sq.index(ts), arena[i-1][j].index(ts+1), 1000);
          if (i < rows-1 && arena[i+1][j].reachable.test(ts))
            net.add_arc(sq.index(ts), arena[i+1][j].index(ts+1), 1000);
          if (j > 0 && arena[i][j-1].reachable.test(ts))
            net.add_arc(sq.index(ts), arena[i][j-1].index(ts+1), 1000);
          if (j < rows-1 && arena[i][j+1].reachable.test(ts))
            net.add_arc(sq.index(ts), arena[i][j+1].index(ts+1), 1000);
        }
      }
    }

  cout << int(net.calc_maxflow(0, 1)) << '\n';
  return 0;
}
